\item[S1] ULAM.AI and the UnsolvedMath Contributors, \emph{UnsolvedMath: A Curated Collection of Open Mathematics Problems}, record 2302017 (AMR-022-2017). CC BY 4.0. \url{https://huggingface.co/datasets/ulamai/UnsolvedMath}.
\item[S2] W. K. Hayman and E. F. Lingham, \emph{Research Problems in Function Theory} (2018), Chapter 2, Problem 2.17 and Update 2.17. \url{https://arxiv.org/abs/1809.07200}.
\end{description}
